#!/usr/bin/env python3
"""
Mario optimiser benchmark -- standalone runner for a Kaggle job.

One file: it writes the whole mario_compare project to disk, builds a Python
3.13 environment (nes-py 9.0.1 needs >= 3.13), runs every algorithm x every
seed in parallel on 1M frames each, and writes a summary.

How to run on Kaggle:
  1. New Notebook -> File -> Import Notebook is NOT needed: just upload this file
     as a Script (or paste it into one notebook cell).
  2. Settings: Accelerator = None (CPU; a GPU does not help, the NES emulator is
     CPU-only). Internet = ON (packages are downloaded at start).
  3. "Save Version" -> "Save & Run All (Commit)". It runs in the background,
     up to Kaggle's 12-hour limit.
  4. When it finishes: Output tab -> download mario_results.zip, or read
     results/summary.txt there.

Everything lands in OUTPUT_DIR (/kaggle/working on Kaggle). The summary is
rewritten after every finished run, so a run cut short still keeps its results.

Edit the CONFIG block below to change what runs.
"""

import csv, os, shutil, subprocess, sys, time
from pathlib import Path

# =============================================================================
# CONFIG
# =============================================================================
BUDGET = 1_000_000          # emulator frames per run (same for every method)
SEEDS = [0, 1, 2]           # run seeds; 3 per method gives mean +- std
SMOKE_TEST = os.environ.get("MARIO_SMOKE") == "1"   # or set True: 30k frames, seed 0 only (~10 min) -- checks the setup works
STOP_LAUNCHING_AFTER_H = 9.5   # no new runs start after this many hours
HARD_STOP_H = 11.5             # running jobs are killed here (Kaggle stops at 12 h)
WORKERS = None              # parallel runs; None = number of CPU cores

# What runs, slowest first (they start first, so the fast ones fill in around them).
# name, module, extra arguments. Each runs once per seed.
METHODS = [
    ("dqn",       "experiments.run_dqn",       []),
    ("ppo",       "experiments.run_ppo",       []),
    ("a2c",       "experiments.run_a2c",       []),
    ("ga",        "experiments.run_ga",        ["--sigma", "0.05", "--crossover"]),
    ("es",        "experiments.run_es",        ["--sigma", "0.05", "--lr", "0.03"]),
    ("cmaes",     "experiments.run_cmaes",     []),
    ("cem",       "experiments.run_cem",       []),
    ("hc",        "experiments.run_hc",        []),
    ("novelty",   "experiments.run_novelty",   []),
    ("mapelites", "experiments.run_mapelites", []),
    ("random",    "experiments.run_baselines", []),   # also runs the scripted baselines
]

ON_KAGGLE = Path("/kaggle/working").exists()
OUTPUT_DIR = Path("/kaggle/working") if ON_KAGGLE else Path.cwd() / "mario_kaggle_out"
VENV_DIR = Path("/tmp/mario_venv")            # outside the output: not saved, not counted
# Set MARIO_PYTHON to an existing interpreter that already has the packages to skip setup.
PREBUILT_PYTHON = os.environ.get("MARIO_PYTHON")

PACKAGES = ["nes-py==9.0.1", "gym-super-mario-bros==9.1.0", "gymnasium==1.3.0",
            "numpy", "opencv-python-headless", "cma", "stable-baselines3"]

